410	  '"turnSeconds":0,"status":"waiting","createdAt":"2026-03-04T07:08:09Z"}';
411	// 七个展示字段全部是对象或数组：每个单元格都只显示“字段格式异常”，
412	// 规则对象里即使带 "v":"ludo" 也不能映射出“飞行棋”，内部内容一律不展开。
413	const BAD_ALL =
414	  '{"id":{"v":"内嵌编号"},"name":["数组名称"],"game":{"v":"ludo"},' +
415	  '"capacity":{"v":4},"turnSeconds":[30],"status":{"v":"waiting"},' +
416	  '"createdAt":{"v":"2026-03-05T00:00:00Z"}}';
417	// 同一房间只有人数与时间两个字段异常：只替换这两个单元格，其余照常显示。
418	const BAD_MIX =
419	  '{"id":"bad-mix","name":"部分异常房","game":"ludo","capacity":[3],' +
420	  '"turnSeconds":{"v":60},"status":"waiting","createdAt":"2026-03-06T09:10:11Z",' +
421	  '"note":"附带字段保留"}';
422	const BAD_FIELD_TEXT = '字段格式异常';
423	
424	// 异常字段只影响所在单元格：前后的正常房间行照常显示，异常对象仍是一行、
425	// 按相对次序排列且不计跳过；异常人数/时间不附“人/秒”，异常创建时间没有
426	// 悬浮说明，任何内部内容都不展开上屏。
427	test('异常字段（对象/数组）只替换所在单元格，不拖累同房间其他字段或其他房间行', { timeout: 60000 }, async (t) => {
428	  const { page } = await setupMixedPage(t, [OK_BEFORE, BAD_NAME, OK_AFTER, BAD_ALL, BAD_MIX]);
429	
430	  await waitForRowCount(page, 5);
431	  // 含异常字段的对象仍然成行，不产生任何跳过计数，更不是加载失败。
432	  const list = await readListArea(page);
433	  assert.equal(list.errorText, null, '异常字段不能让整份列表加载失败');
434	  assert.equal(list.skipCount, 0, '含异常字段的对象不应被跳过或计数');
435	  assert.equal(list.skipText, null);
436	
437	  const rows = await readRows(page);
438	
439	  // 异常房间之前的正常房间不受影响。
440	  assert.deepEqual(rows[0].cells.slice(0, 6), [
441	    'ok-before', '正常前房间', '五子棋', '2 人', '不限时', '未开始',
442	  ]);
443	  assert.equal(rows[0].timeTitle, '2026-03-02T01:02:03Z');
444	
445	  // 名称为 {"toString":"旧名称"} 的房间：只有名称单元格异常，其余字段照常；
446	  // “旧名称”绝不能被展开或经 toString 转换后上屏。
447	  assert.deepEqual(rows[1].cells.slice(0, 6), [
448	    'bad-name', BAD_FIELD_TEXT, '五子棋', '2 人', '不限时', '未开始',
449	  ]);
450	  assert.match(rows[1].cells[6], /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/);
451	  assert.equal(rows[1].badge, '未开始');
452	  assert.equal(rows[1].timeTitle, '2026-03-04T07:08:09Z');
453	  assert.ok(!list.text.includes('旧名称'), '异常名称的内部内容不能展开上屏');
454	
455	  // 异常房间之后的正常房间同样不受影响（证明它前后的房间都能查看）。
456	  assert.deepEqual(rows[2].cells.slice(0, 6), [
457	    'ok-after', '正常后房间', '飞行棋', '3 人', '300 秒', 'playing',
458	  ]);
459	
460	  // 七个字段全部异常：七个单元格全部只显示异常文案，状态徽标也不例外；
461	  // 规则对象不映射中文名，人数/时间不附单位，创建时间没有 title 悬浮说明。
462	  assert.deepEqual(rows[3].cells, [
463	    BAD_FIELD_TEXT, BAD_FIELD_TEXT, BAD_FIELD_TEXT, BAD_FIELD_TEXT,
464	    BAD_FIELD_TEXT, BAD_FIELD_TEXT, BAD_FIELD_TEXT,
465	  ]);
466	  assert.equal(rows[3].badge, BAD_FIELD_TEXT, '异常状态应显示字段格式异常');
467	  assert.equal(rows[3].timeTitle, null, '异常创建时间不应附带日期悬浮说明');
468	
469	  // 只有部分字段异常的房间：其余字段（含中文规则名、未开始徽标、时间格式）照常。
470	  assert.deepEqual(rows[4].cells.slice(0, 6), [
471	    'bad-mix', '部分异常房', '飞行棋', BAD_FIELD_TEXT, BAD_FIELD_TEXT, '未开始',
472	  ]);
473	  assert.match(rows[4].cells[6], /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/);
474	  assert.equal(rows[4].badge, '未开始');
475	  assert.equal(rows[4].timeTitle, '2026-03-06T09:10:11Z');
476	
477	  // 所有异常字段的内部内容都不能上屏。
478	  for (const leaked of ['内嵌编号', '数组名称', '"v"', '附带字段保留']) {
479	    assert.ok(!list.text.includes(leaked), '异常字段内部内容不应展开上屏：' + leaked);
480	  }
481	});
482	
483	// 异常对象位于开头、中间或末尾，都不能导致其他对象行被省略。
484	test('异常对象位于开头/中间/末尾，其他房间行都不省略且次序不变', { timeout: 60000 }, async (t) => {
485	  const layouts = [
486	    [BAD_NAME, OK_BEFORE, OK_AFTER],
487	    [OK_BEFORE, BAD_NAME, OK_AFTER],
488	    [OK_BEFORE, OK_AFTER, BAD_NAME],
489	  ];
490	  for (const records of layouts) {
491	    const { page } = await setupMixedPage(t, records);
492	    await waitForRowCount(page, 3);
493	    const list = await readListArea(page);
494	    assert.equal(list.errorText, null);
495	    assert.equal(list.rowCount, 3, '异常对象位于任意位置都不能省略其他房间行');
496	    assert.deepEqual(
497	      (await readRows(page)).map((r) => r.cells[0]),
498	      records.map((rec, i) => JSON.parse(rec).id || ''),
499	      '房间行次序应与接口中对象的相对次序一致',
500	    );
501	  }
502	});
503	
504	// 即使所有对象行都含异常字段，也要保留表格和这些行：不显示空列表提示，
505	// 也不显示“全部跳过”的说明（异常对象根本不计入跳过）。
506	test('所有房间行都含异常字段：保留表格与全部行，无空列表提示、无跳过提示、无加载失败', { timeout: 60000 }, async (t) => {
507	  const allBad = [
508	    BAD_NAME,
509	    '{"id":"all-bad-1","name":["名称甲"],"game":"gomoku","capacity":2,"turnSeconds":0,' +
510	      '"status":"waiting","createdAt":"2026-03-07T00:00:00Z"}',
511	    '{"id":"all-bad-2","name":{"x":"名称乙"},"game":{"v":"ludo"},"capacity":{"x":3},' +
512	      '"turnSeconds":[60],"status":["waiting"],"createdAt":["2026-03-08T00:00:00Z"]}',
513	  ];
514	  const { page } = await setupMixedPage(t, allBad);
515	
516	  await waitForRowCount(page, 3);
517	  // 给页面足够时间，确认不会迟来一个空提示或跳过说明。
518	  await new Promise((resolve) => setTimeout(resolve, 300));
519	  const list = await readListArea(page);
520	
521	  assert.equal(list.hasTable, true, '全部行含异常字段时仍应保留表格');
522	  assert.equal(list.rowCount, 3);
523	  assert.equal(list.errorText, null);
524	  assert.equal(list.skipText, null, '异常字段对象不计入跳过，不应出现跳过提示');
525	  assert.deepEqual(list.emptyTexts, [], '不能把含异常字段的房间当成空列表');
526	  assert.ok(!list.text.includes(EMPTY_TEXT));
527	
528	  const rows = await readRows(page);
529	  assert.equal(rows[0].cells[1], BAD_FIELD_TEXT);
530	  assert.equal(rows[1].cells[1], BAD_FIELD_TEXT);
531	  assert.deepEqual(rows[1].cells.slice(2, 6), ['五子棋', '2 人', '不限时', '未开始']);
532	  assert.match(rows[1].cells[6], /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/);
533	  // 第三行除编号外的展示字段全部异常：逐格替换，编号仍正常显示。
534	  assert.equal(rows[2].cells[0], 'all-bad-2');
535	  assert.deepEqual(rows[2].cells.slice(1), [
536	    BAD_FIELD_TEXT, BAD_FIELD_TEXT, BAD_FIELD_TEXT, BAD_FIELD_TEXT,
537	    BAD_FIELD_TEXT, BAD_FIELD_TEXT,
538	  ]);
539	  assert.equal(rows[2].timeTitle, null);
540	});
541	
542	// 异常旧记录不能妨碍新房间显示：创建成功提示不能变成失败，列表刷新后
543	// 旧异常记录原位保留、新房间照常追加，服务端原始记录不被删除、改写或展开。
544	test('异常旧记录下创建房间：成功提示保留、新房间追加、旧记录与附带字段原位保留', { timeout: 60000 }, async (t) => {
545	  const seed = [BAD_NAME, OK_BEFORE, 'null', '"误入的字符串"'];
546	  const { page, baseURL } = await setupMixedPage(t, seed);
547	
548	  await waitForRowCount(page, 2);
549	  await waitForSkipNotice(page);
550	
551	  const createdPromise = nextCreated(page);
552	  await fillGomokuForm(page, '异常数据下新建的房间', 0);
553	  await waitForMessageKind(page, 'ok');
554	  const created = await createdPromise;
555	  assert.ok(created.id, '异常旧记录不能把创建成功变成失败');
556	
557	  await waitForRowCount(page, 3);
558	  const list = await readListArea(page);
559	  assert.equal(list.rowCount, 3);
560	  assert.equal(list.errorText, null);
561	  assert.equal(
562	    list.skipText,
563	    '有 2 条房间记录无法作为房间显示，已跳过；原始数据仍保留在服务端，未被删除或改写。',
564	    '创建房间不应改变非对象记录的跳过计数',
565	  );
566	
567	  const rows = await readRows(page);
568	  assert.deepEqual(
569	    rows.map((r) => r.cells[0]),
570	    ['bad-name', 'ok-before', created.id],
571	    '异常旧记录原位保留，新房间追加为最后一行',
572	  );
573	  assert.equal(rows[0].cells[1], BAD_FIELD_TEXT, '旧异常记录刷新后仍是异常单元格');
574	  assert.equal(rows[2].cells[1], created.name);
575	  assert.equal(rows[2].cells[4], '不限时');
576	  assert.equal(rows[2].badge, '未开始');
577	
578	  // 服务端原始记录一条不少、原位保留：异常名称仍是同一个对象，非对象记录
579	  // 类型不变，新对象追加在最后；查看列表与创建都没有改写或展开旧记录。
580	  const serverRooms = await readServerRooms(baseURL);
581	  assert.equal(serverRooms.length, 5, '两条对象记录、两条非对象记录与新房间合计 5 条');
582	  assert.deepEqual(serverRooms[0], JSON.parse(BAD_NAME), '异常名称对象必须原样保留');
583	  assert.deepEqual(serverRooms[1], JSON.parse(OK_BEFORE));
584	  assert.deepEqual(serverRooms.slice(2, 4), [null, '误入的字符串']);
585	  assert.equal(serverRooms[4].id, created.id, '新房间应保存在最后');
586	});
587	
588	test('混合记录下创建房间：原始记录原位保留，新房间追加为最后一行，跳过计数不变', { timeout: 60000 }, async (t) => {
589	  const seed = [R1, 'null', '"误入的字符串"', 'false', R2];
590	  const { page, baseURL } = await setupMixedPage(t, seed);
591	
592	  await waitForRowCount(page, 2);
593	  await waitForSkipNotice(page);
594	  let list = await readListArea(page);
595	  assert.equal(
596	    list.skipText,
597	    '有 3 条房间记录无法作为房间显示，已跳过；原始数据仍保留在服务端，未被删除或改写。',
598	  );
599	
600	  const createdPromise = nextCreated(page);
601	  await fillGomokuForm(page, '混排中新建的房间', 0);
602	  await waitForMessageKind(page, 'ok');
603	  const created = await createdPromise;
604	  assert.ok(created.id, '创建结果应包含新房间编号');
605	
606	  // 列表刷新后：原有两个房间与新房间共 3 行，非对象记录仍跳过同样的 3 条。
607	  await waitForRowCount(page, 3);
608	  list = await readListArea(page);
609	  assert.equal(list.rowCount, 3);
610	  assert.equal(
611	    list.skipText,
612	    '有 3 条房间记录无法作为房间显示，已跳过；原始数据仍保留在服务端，未被删除或改写。',
613	    '创建房间不应改变跳过条数或保留说明',
614	  );
615	  const rows = await readRows(page);
616	  assert.deepEqual(
617	    rows.map((r) => r.cells[0]),
618	    ['mix-alpha', 'mix-beta', created.id],
619	    '新房间应作为对象追加在原有房间之后，原始次序不变',
620	  );
621	  assert.equal(rows[2].cells[1], created.name);
622	  assert.equal(rows[2].cells[4], '不限时');
623	  assert.equal(rows[2].badge, '未开始');
624	
625	  // 服务端记录：5 条原始记录原位保留（含类型与附带字段），新对象追加在最后。
626	  const serverRooms = await readServerRooms(baseURL);
627	  assert.equal(serverRooms.length, 6, '原始记录一条不少，另加新建房间');
628	  assert.deepEqual(serverRooms.slice(0, 5), [
629	    JSON.parse(R1), null, '误入的字符串', false, JSON.parse(R2),
630	  ], '原始记录的数量、次序、类型与附带字段必须原位保留');
631	  assert.equal(serverRooms[5].id, created.id, '新房间应保存在最后');
632	});
