// （如状态列的徽标），缺省时整格替换为异常文案。
var ROOM_COLUMNS = [
  {
    key: 'id',
    className: 'id',
    render: function (td, value) { td.textContent = value || ''; }
  },
  {
    key: 'name',
    render: function (td, value) { td.textContent = value || ''; }
  },
  {
    key: 'game',
    render: function (td, value) {
      td.textContent = GAME_LABELS[value] || value || '';
    }
  },
  {
    key: 'capacity',
    render: function (td, value) {
      td.textContent = (value != null ? value : '') + ' 人';
    }
  },
  {
    key: 'turnSeconds',
    render: function (td, value) {
      td.textContent = value === 0 ? '不限时' : value + ' 秒';
    }
  },
  {
    key: 'status',
    render: function (td, value) {
      appendBadge(td, STATUS_LABELS[value] || value || '');
    },
    // 异常状态仍在原有徽标中显示提示文案。
    renderBad: function (td) { appendBadge(td, BAD_FIELD_TEXT); }
  },
  {
    key: 'createdAt',
    render: function (td, value) {
      var t = formatTime(value || '');
      td.textContent = t.text;
      td.title = t.title;
    }
    // 无 renderBad：异常创建时间只显示异常文案，不附加日期悬浮说明
    // （不设置 title）。
  }
];

// 逐列渲染一个房间行：任何字段异常都只替换该单元格，其余字段照常显示。
function buildRoomRow(r) {
  var tr = document.createElement('tr');
  ROOM_COLUMNS.forEach(function (col) {
    var td = document.createElement('td');
    if (col.className) td.className = col.className;
    var value = r[col.key];
    if (isAbnormalField(value)) {
      if (col.renderBad) col.renderBad(td);
      else markBadCell(td);
    } else {
      col.render(td, value);
    }
    tr.appendChild(td);
  });
  return tr;
}

