}

// 历史记录的某个展示字段若被存成 JSON 对象或数组，该单元格统一显示
// “字段格式异常”，不展开其内部内容；异常只影响所在单元格，绝不能抛出
// 异常拖垮整行乃至整份列表。null、字符串、数字、布尔值及缺失字段都不算
// 异常，仍走各列原有的展示与兜底。
var BAD_FIELD_TEXT = '字段格式异常';
function isAbnormalField(value) {
  return value !== null && typeof value === 'object';
}
function markBadCell(td) {
  td.textContent = BAD_FIELD_TEXT;
}

function appendBadge(td, text) {
  var badge = document.createElement('span');
  badge.className = 'badge';
  badge.textContent = text;
  td.appendChild(badge);
}

// 七列的展示定义，顺序即表格列顺序（表头也由同一份定义生成）。每列只
// 描述“正常值如何显示”（含各列原有的兜底行为）；对象/数组的异常判定
// 与替换由 buildRoomRow 统一处理，不在各列重复维护。个别列可用
// renderBad 保留原有容器（如状态列的徽标），缺省时整格替换为异常文案。
var ROOM_COLUMNS = [
  {
    key: 'id',
    label: '房间编号',
    className: 'id',
    render: function (td, value) { td.textContent = value || ''; }
  },
  {
    key: 'name',
    label: '名称',
    render: function (td, value) { td.textContent = value || ''; }
  },
  {
    key: 'game',
    label: '规则',
    render: function (td, value) {
      td.textContent = GAME_LABELS[value] || value || '';
    }
  },
  {
    key: 'capacity',
    label: '人数上限',
    render: function (td, value) {
      td.textContent = (value != null ? value : '') + ' 人';
    }
  },
  {
    key: 'turnSeconds',
    label: '时间限制',
    render: function (td, value) {
      td.textContent = value === 0 ? '不限时' : value + ' 秒';
    }
  },
  {
    key: 'status',
    label: '状态',
    render: function (td, value) {
      appendBadge(td, STATUS_LABELS[value] || value || '');
    },
    // 异常状态仍在原有徽标中显示提示文案。
    renderBad: function (td) { appendBadge(td, BAD_FIELD_TEXT); }
  },
  {
    key: 'createdAt',
    label: '创建时间',
    render: function (td, value) {
      var t = formatTime(value || '');
      td.textContent = t.text;
      td.title = t.title;
    }
    // 无 renderBad：异常创建时间只显示异常文案，不附加日期悬浮说明
    // （不设置 title）。
  }
];

// 逐列渲染一个房间行：任何字段异常都只替换该单元格，其余字段照常显示。
function buildRoomRow(r) {
  var tr = document.createElement('tr');
  ROOM_COLUMNS.forEach(function (col) {
    var td = document.createElement('td');
    if (col.className) td.className = col.className;
    var value = r[col.key];
    if (isAbnormalField(value)) {
      if (col.renderBad) col.renderBad(td);
      else markBadCell(td);
    } else {
      col.render(td, value);
    }
    tr.appendChild(td);
  });
  return tr;
}

function renderRooms(rooms) {
  listArea.innerHTML = '';

  var validRooms = [];
  var skipped = 0;
  rooms.forEach(function (r) {
    if (isRoomRecord(r)) validRooms.push(r);
    else skipped++;
  });

  if (!validRooms.length) {
    if (skipped > 0) {
      appendSkipNotice(skipped, true);
    } else {
      var pEmpty = document.createElement('p');
      pEmpty.className = 'empty';
      pEmpty.textContent = '还没有房间记录。';
      listArea.appendChild(pEmpty);
    }
    return;
  }

  if (skipped > 0) appendSkipNotice(skipped, false);

  var table = document.createElement('table');
  var thead = document.createElement('thead');
  var headRow = document.createElement('tr');
  ROOM_COLUMNS.forEach(function (col) {
    var th = document.createElement('th');
    th.textContent = col.label;
    headRow.appendChild(th);
  });

